import openpyxl
from openpyxl.utils import get_column_letter

path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
print('sheets:', wb.sheetnames)
ws=wb['Task']

# Collect formula cells of interest
blocks = []
# Step1 blocks
for r in range(12,18):
    for c in range(8,13):
        blocks.append((r,c))
for r in range(19,25):
    for c in range(8,13):
        blocks.append((r,c))
for r in range(26,32):
    for c in range(8,13):
        blocks.append((r,c))
# Net balance
for r in range(35,41):
    for c in range(8,13):
        blocks.append((r,c))
# Stats
for r in range(42,48):
    for c in range(8,13):
        blocks.append((r,c))
# Weighted mean
for c in range(8,13):
    blocks.append((50,c))

bad=[]
for r,c in blocks:
    v=ws.cell(r,c).value
    if not (isinstance(v,str) and v.startswith('=')):
        bad.append((ws.cell(r,c).coordinate, v))

print('Total targeted cells:', len(blocks))
print('Non-formula cells among targeted:', len(bad))
if bad:
    for coord,v in bad[:20]:
        print('  ',coord,repr(v))

# Spot-check sample formulas
samples=['H12','L17','H19','L24','H26','L31','H35','L40','H42','L47','H50','L50']
print('\nSample formulas:')
for coord in samples:
    print(coord, ws[coord].value)

# Confirm no new sheets
if set(wb.sheetnames)!=set(['Task','Data']):
    print('WARNING: unexpected sheets:', wb.sheetnames)

wb.close()
print('done')
